INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (104, 194, 'CPP Film (Cast polypropylene film)', '../upload/image/20181226/20181226141347_55980.jpg', '<p></p><p><span style="color:#009900;font-family:Verdana;">CPP Film (Cast polypropylene film)</span></p> <p><span style="color:#009900;font-family:Verdana;">CPP film (cast polypropylene film) were used for food and medicine flexible packaging, as well as dry-compounded with BOPET,BOPP,BOPA etc. Characters: Excellent clarity ,good for protection against the moisture, excellent printing and compounding, low heat seal temperature </span><br/> <span style="color:#009900;font-family:Verdana;"> CPP film (cast Polypropylene film) included plain/general cast PP film,Retort cast polypropylene film, cpp laminating film,cpp packing film,VMCPP film, white twist CPP packing materials </span><br/> <span style="color:#009900;font-family:Verdana;"> Color: Clear/transparent Thickness :20-40UM ,75-150UM </span><br/> <span style="color:#009900;font-family:Verdana;"> Width :325-1100MM Length :3000M,4000M,6000M Inner core :3''(76MM),6''(152MM).</span><br/> <span style="color:#009900;font-family:Verdana;"> Applications: food and medicine flexible packaging. </span><br/> <span style="color:#009900;font-family:Verdana;"> Type: Tissue film, antifog film, the antistatic film, the FINISHING film, automatic packaging film ,inflatable packaging film ,aluminum substrate film, temperature cooking film</span></p> <p><br/></p>', '2026-09-06 20:58:45');